const LINTER_SCRIPT_PATH = join(
  cqmsRepoRoot,
  '.github/skills/linter-checker/scripts/generate-linter-report.mjs',
);

type RunQueuedScanArgs = {
  readonly hub: RunStatusHub;
  readonly scan: QueuedScanRow;
};

const publishStatus = (
  hub: RunStatusHub,
  scan: QueuedScanRow,
  status: string,
): void => {
  hub.publish(scan.run_id, {
    runId: scan.run_id,
    scanId: scan.scan_id,
    scannerId: scan.scanner_id,
    status,
    type: 'scan-status',
  });
};

const runDeterministicLinter = async (
  scan: QueuedScanRow,
  outputDirectory: string,
): Promise<'failed' | 'succeeded'> => {
  try {
    execFileSync(
      'node',
      [
        LINTER_SCRIPT_PATH,
        `--target=${scan.local_path}`,
        `--scope=${scan.scope_value || '.'}`,
        `--output-dir=${outputDirectory}`,
        '--skip-ingest',
      ],
      { encoding: 'utf8' },
    );
  } catch (error) {
    // Real execution failures already degrade to a report.json noting the
    // failure (the script's own resilience, ADR-015) — this catch only
    // covers the script itself failing to even start.
    console.error(`❌ linter-checker script failed to run:`, error);
  }

  const reportMarkdownPath = join(outputDirectory, 'report.md');
  const reportJsonPath = join(outputDirectory, 'report.json');

  if (!existsSync(reportMarkdownPath) || !existsSync(reportJsonPath)) {
    await markScanFailed({
      errorMessage: 'linter-checker script did not produce report files.',
      runId: scan.run_id,
      scanId: scan.scan_id,
    });
    return 'failed';
  }

  const rawJsonPath = join(outputDirectory, 'linter.raw.json');

  await ingestReport({
    localPath: scan.local_path,
    origin: 'ui_agent_sdk',
    rawJsonPath: existsSync(rawJsonPath) ? rawJsonPath : undefined,
    reportJsonPath,
    reportMarkdownPath,
    runId: scan.run_id,
    scannerId: 'linter',
    scopeType: scan.scope_type as 'changed-files' | 'diff' | 'folder' | 'repo',
    scopeValue: scan.scope_value,
  });
  return 'succeeded';
};

const runAgentSkill = async (
  scan: QueuedScanRow,
  outputDirectory: string,
  hub: RunStatusHub,
): Promise<'failed' | 'succeeded'> => {
  const result = await runSkillAgent({
    onProgress: (message) => {
      updateScanProgress({
        progressMessage: message,
        scanId: scan.scan_id,
      }).catch((error: unknown) => {
        console.error('❌ Failed to persist scan progress:', error);
      });
      hub.publish(scan.run_id, {
        runId: scan.run_id,
        scanId: scan.scan_id,
        scannerId: scan.scanner_id,
        status: message,
        type: 'scan-progress',
      });
    },
    outputDirectory,
    scannerId: scan.scanner_id as
      | 'code-smell-checker'
      | 'code-smell-zen'
      | 'fallow',
    scopeArgument: scan.scope_value === '.' ? undefined : scan.scope_value,
    skillPath: scan.skill_path,
    targetProjectPath: scan.local_path,
  });

  if (!result.success || !result.reportMarkdownPath || !result.reportJsonPath) {
    await markScanFailed({
      errorMessage:
        result.errorMessage ?? 'Agent session did not produce a report.',
      runId: scan.run_id,
      scanId: scan.scan_id,
    });
    return 'failed';
  }

  // Only fallow's skill produces a raw artifact today (TECH_SPEC §2.4).
  const rawJsonPath = join(outputDirectory, 'fallow.raw.json');

  await ingestReport({
    localPath: scan.local_path,
    origin: 'ui_agent_sdk',
    rawJsonPath:
      scan.scanner_id === 'fallow' && existsSync(rawJsonPath)
        ? rawJsonPath
        : undefined,
    reportJsonPath: result.reportJsonPath,
    reportMarkdownPath: result.reportMarkdownPath,
    runId: scan.run_id,
    scannerId: scan.scanner_id as
      | 'code-smell-checker'
      | 'code-smell-zen'
      | 'fallow',
    scopeType: scan.scope_type as 'changed-files' | 'diff' | 'folder' | 'repo',
    scopeValue: scan.scope_value,
  });
  return 'succeeded';
};

/**
 * Executes one queued scan end to end (TECH_SPEC §2.7): marks it running,
 * branches per scanners.deterministic exactly as originally planned
 * (§2.5) — linter via a plain child process, the other three via
 * @repo/agent-runner — then ingests the result or marks the scan failed.
 * Any unexpected error here is caught and turned into a failed scan
 * rather than crashing the whole orchestrator process; one bad scan must
 * not take down the queue for every other project.
 */
export const runQueuedScan = async ({
  hub,
  scan,
}: RunQueuedScanArgs): Promise<void> => {
  await markScanRunning({ scanId: scan.scan_id });
  publishStatus(hub, scan, 'running');

  const outputDirectory = join(
    cqmsRepoRoot,
    '.tmp',
    'scan-orchestrator',
    scan.scan_id,
  );
  mkdirSync(outputDirectory, { recursive: true });

  let finalStatus: 'failed' | 'succeeded';
  try {
    finalStatus = scan.deterministic
      ? await runDeterministicLinter(scan, outputDirectory)
      : await runAgentSkill(scan, outputDirectory, hub);
  } catch (error) {
    console.error(`❌ Scan ${scan.scan_id} failed unexpectedly:`, error);
    await markScanFailed({
      errorMessage: error instanceof Error ? error.message : String(error),
      runId: scan.run_id,
      scanId: scan.scan_id,
    });
    finalStatus = 'failed';
  }

  publishStatus(hub, scan, finalStatus);
};

import { createServer, type Server } from 'node:http';

/**
 * Plain node:http server — no Express, no @react-router/express adapter
 * (TECH_SPEC §2.7): this process never serves CRUD or React Router
 * traffic, only the WebSocket upgrade at /ws/runs and a bare health check.
 */
export const createHttpServer = (): Server =>
  createServer((request, response) => {
    if (request.url === '/healthz') {
      response.writeHead(200, { 'Content-Type': 'text/plain' });
      response.end('ok');
      return;
    }

    response.writeHead(404);
    response.end();
  });

import { describe, expect, it, vi } from 'vitest';

import { createRunStatusHub } from './runStatusHub.ts';

const OPEN = 1;
const CLOSED = 3;

const createFakeSocket = (readyState: number) => {
  const listeners = new Map<string, () => void>();
  return {
    on: vi.fn((event: string, handler: () => void) => {
      listeners.set(event, handler);
    }),
    OPEN,
    readyState,
    send: vi.fn(),
    triggerClose: () => listeners.get('close')?.(),
  };
};

describe('createRunStatusHub', () => {
  it('sends a message to every socket subscribed to a run', () => {
    const hub = createRunStatusHub();
    const socketA = createFakeSocket(OPEN);
    const socketB = createFakeSocket(OPEN);

    hub.subscribe('run-1', socketA as never);
    hub.subscribe('run-1', socketB as never);

    hub.publish('run-1', {
      runId: 'run-1',
      scanId: 'scan-1',
      scannerId: 'linter',
      status: 'running',
      type: 'scan-status',
    });

    expect(socketA.send).toHaveBeenCalledTimes(1);
    expect(socketB.send).toHaveBeenCalledTimes(1);
    expect(JSON.parse(socketA.send.mock.calls[0]?.[0] as string)).toEqual({
      runId: 'run-1',
      scanId: 'scan-1',
      scannerId: 'linter',
      status: 'running',
      type: 'scan-status',
    });
  });

  it('does not send to sockets subscribed to a different run', () => {
    const hub = createRunStatusHub();
    const socket = createFakeSocket(OPEN);

    hub.subscribe('run-1', socket as never);
    hub.publish('run-2', {
      runId: 'run-2',
      scanId: 'scan-2',
      scannerId: 'linter',
      status: 'running',
      type: 'scan-status',
    });

    expect(socket.send).not.toHaveBeenCalled();
  });

  it('does not send to a closed socket', () => {
    const hub = createRunStatusHub();
    const socket = createFakeSocket(CLOSED);

    hub.subscribe('run-1', socket as never);
    hub.publish('run-1', {
      runId: 'run-1',
      scanId: 'scan-1',
      scannerId: 'linter',
      status: 'running',
      type: 'scan-status',
    });

    expect(socket.send).not.toHaveBeenCalled();
  });

  it('stops publishing to a socket once it closes', () => {
    const hub = createRunStatusHub();
    const socket = createFakeSocket(OPEN);

    hub.subscribe('run-1', socket as never);
    socket.triggerClose();

    hub.publish('run-1', {
      runId: 'run-1',
      scanId: 'scan-1',
      scannerId: 'linter',
      status: 'running',
      type: 'scan-status',
    });

    expect(socket.send).not.toHaveBeenCalled();
  });

  it('is a no-op when publishing to a run with no subscribers', () => {
    const hub = createRunStatusHub();
    expect(() =>
      hub.publish('no-subscribers', {
        runId: 'no-subscribers',
        scanId: 'scan-1',
        scannerId: 'linter',
        status: 'running',
        type: 'scan-status',
      }),
    ).not.toThrow();
  });
});

import type { WebSocket } from 'ws';

export type RunStatusPayload = {
  readonly runId: string;
  readonly scanId: string;
  readonly scannerId: string;
  readonly status: string;
  readonly type: 'scan-progress' | 'scan-status';
};

/**
 * In-memory Map<runId, Set<WebSocket>> (TECH_SPEC §2.7) — lives in this
 * process because execution and the hub now share one process (the whole
 * point of the two-process redesign, ADR-015): publishing is a plain
 * function call, not a cross-process bridge. Not in packages/scan-ingestion,
 * which stays framework-agnostic with no WebSocket concept.
 */
export const createRunStatusHub = () => {
  const subscribers = new Map<string, Set<WebSocket>>();

  const subscribe = (runId: string, socket: WebSocket): void => {
    let sockets = subscribers.get(runId);
    if (!sockets) {
      sockets = new Set();
      subscribers.set(runId, sockets);
    }
    sockets.add(socket);

    socket.on('close', () => {
      sockets?.delete(socket);
      if (sockets?.size === 0) {
        subscribers.delete(runId);
      }
    });
  };

  const publish = (runId: string, payload: RunStatusPayload): void => {
    const sockets = subscribers.get(runId);
    if (!sockets) return;

    const message = JSON.stringify(payload);
    for (const socket of sockets) {
      if (socket.readyState === socket.OPEN) {
        socket.send(message);
      }
    }
  };

  return { publish, subscribe };
};

export type RunStatusHub = ReturnType<typeof createRunStatusHub>;

