} from './wideAlltypes150.constants.js';

export type WideAlltypes150Repository = {
  readonly getPaginated: (
    args: GetPaginatedWideAlltypes150Args,
  ) => Promise<PaginatedResponse<DbRow>>;
};

type CreateWideAlltypes150RepositoryArgs = {
