export const loadSkillFrontmatter = ({
  skillPath,
}: LoadSkillFrontmatterArgs): SkillFrontmatter => {
  const skillMdPath = join(cqmsRepoRoot, skillPath, 'SKILL.md');
  const parsed: null | SkillFrontmatter = parseFrontmatter(skillMdPath);

