import { Pool } from 'pg';

import { readEnvConfig } from './env.schema.ts';

let pool: Pool | undefined;

/**
 * Lazily-initialized singleton — shared across every Node-context consumer
 * of this package (packages/scan-ingestion's CLI + admin_system job code,
 * and potentially apps/api-server(-fast) in the future), none of which is
 * "the" single server process with one obvious place to construct a Pool
 * up front. Each process gets its own module-level singleton via getPool();
 * callers still supply their own DB_NAME et al. via env, so this is not a
 * cross-process shared connection.
 */
export const getPool = (): Pool => {
  if (!pool) {
    const envConfig = readEnvConfig({ env: process.env });
    pool = new Pool({
      database: envConfig.DB_NAME,
      host: envConfig.DB_HOST,
      password: envConfig.DB_PASSWORD,
      port: envConfig.DB_PORT,
      user: envConfig.DB_USER,
    });
  }

  return pool;
};

export const closePool = async (): Promise<void> => {
  if (!pool) {
    return;
  }

  await pool.end();
  pool = undefined;
};

import type { Rule } from 'eslint';

const INTERNAL_PATH_PREFIXES = ['./', '../', '@/'] as const;

const isInternalPath = (source: string): boolean =>
  INTERNAL_PATH_PREFIXES.some((prefix) => source.startsWith(prefix));

const normalizeImportPath = (source: string): string => {
  let normalized = source;

  normalized = normalized.replace(/\/index(?:\.tsx?|\.ts)?$/, '');
  normalized = normalized.replace(/\.tsx?$/, '');

  if (normalized === '.') {
    return './';
  }

  if (normalized === '..') {
    return '../';
  }

  return normalized;
};

const getQuoteCharacter = (rawSourceText: string): "'" | '"' =>
  rawSourceText.startsWith('"') ? '"' : "'";

const reportIfPathNeedsCleanup = ({
  context,
  node,
}: {
  readonly context: Rule.RuleContext;
  readonly node: any;
}): void => {
  const sourceNode = node.source;

  if (!sourceNode || typeof sourceNode.value !== 'string') {
    return;
  }

  const sourceValue = sourceNode.value;
  if (!isInternalPath(sourceValue)) {
    return;
  }

  const cleanedPath = normalizeImportPath(sourceValue);
  if (cleanedPath === sourceValue) {
    return;
  }

  context.report({
    data: {
      cleanedPath,
      sourceValue,
    },
    fix(fixer) {
      const sourceCode = context.sourceCode;
      const originalText = sourceCode.getText(sourceNode);
      const quote = getQuoteCharacter(originalText);
      return fixer.replaceText(sourceNode, `${quote}${cleanedPath}${quote}`);
    },
    messageId: 'cleanImportPath',
    node: sourceNode,
  });
};

const rule: Rule.RuleModule = {
  create(context) {
    return {
      ExportAllDeclaration(node: any) {
        reportIfPathNeedsCleanup({
          context,
          node,
        });
      },
      ExportNamedDeclaration(node: any) {
        reportIfPathNeedsCleanup({
          context,
          node,
        });
      },
      ImportDeclaration(node: any) {
        reportIfPathNeedsCleanup({
          context,
          node,
        });
      },
    };
  },

  meta: {
    docs: {
      description:
        'Enforce extensionless and indexless internal import/export paths',
      recommended: false,
    },
    fixable: 'code',
    messages: {
      cleanImportPath:
        'Use clean path "{{cleanedPath}}" instead of "{{sourceValue}}".',
    },
    schema: [],
    type: 'suggestion',
  },
};

export default rule;

// ✅ Enforces object destructuring for functions with 2+ parameters
// ✅ Skips single-parameter functions
// ❌ Auto-fix disabled (too aggressive for callbacks, Promise constructors, etc.)

import type { Rule } from 'eslint';

const rule: Rule.RuleModule = {
  create(context) {
    return {
      ArrowFunctionExpression(node: any) {
        checkFunction(node, context);
      },
      FunctionDeclaration(node: any) {
        checkFunction(node, context);
      },
      FunctionExpression(node: any) {
        checkFunction(node, context);
      },
    };
  },
  meta: {
    docs: {
      description:
        'Enforce object parameter pattern for functions with multiple parameters',
      recommended: false,
    },
    messages: {
      useObjectParam:
        'Functions with multiple parameters should use a single object parameter with a named type.',
    },
    schema: [],
    type: 'suggestion',
  },
};

function checkFunction(node: any, context: Rule.RuleContext) {
  const params = node.params;

  // Skip if single parameter or no parameters
  if (params.length <= 1) {
    return;
  }

  // Skip if already using object destructuring pattern
  if (params.length === 1 && params[0].type === 'ObjectPattern') {
    return;
  }

  // Skip array method callbacks (map, filter, forEach, reduce, etc.)
  if (isArrayMethodCallback(node)) {
    return;
  }

  // Report violation
  context.report({
    messageId: 'useObjectParam',
    node,
  });
}

function isArrayMethodCallback(node: any): boolean {
  const parent = node.parent;

  // Check if this function is a direct argument to a call expression
  if (parent?.type === 'CallExpression') {
    const callee = parent.callee;

    // Check for array methods (map, filter, forEach, find, findIndex, some, every, reduce, etc.)
    if (callee?.type === 'MemberExpression') {
      const methodName = callee.property?.name;
      const objectName =
        callee.object?.type === 'Identifier' ? callee.object.name : undefined;
      const arrayMethods = [
        'map',
        'filter',
        'forEach',
        'find',
        'findIndex',
        'some',
        'every',
        'reduce',
        'reduceRight',
        'flatMap',
        'sort',
        'toSorted',
        'findLast',
        'findLastIndex',
      ];

      return (
        arrayMethods.includes(methodName) ||
        (objectName === 'Array' && methodName === 'from')
      );
    }
  }

  return false;
}

export default rule;

/**
 * Custom ESLint rule to merge duplicate imports from the same source
 * Enforces: import { A, B } from './module'
 * Disallows: import { A } from './module'; import { B } from './module'
 */

import type { Rule } from 'eslint';

const createSourceMap = (programNode: any): Map<string, any[]> => {
  const sourceMap = new Map<string, any[]>();
  const imports = programNode.body.filter(
    (statement: any) => statement.type === 'ImportDeclaration',
  );

  for (const importNode of imports) {
    const source = importNode.source.value as string;
    const existingImports = sourceMap.get(source) ?? [];
    existingImports.push(importNode);
    sourceMap.set(source, existingImports);
  }

  return sourceMap;
};

const hasSameImportKind = (importNodes: any[]): boolean => {
  if (importNodes.length === 0) {
    return false;
  }

  const firstImportKind = importNodes[0].importKind;
  return importNodes.every(
    (importNode: any) => importNode.importKind === firstImportKind,
  );
};

const getSpecifierText = (specifier: any): string | undefined => {
  if (specifier.type === 'ImportSpecifier') {
    if (specifier.imported.name === specifier.local.name) {
      return specifier.imported.name;
    }

    return `${specifier.imported.name} as ${specifier.local.name}`;
  }

  if (specifier.type === 'ImportDefaultSpecifier') {
    return `default as ${specifier.local.name}`;
  }

  if (specifier.type === 'ImportNamespaceSpecifier') {
    return `* as ${specifier.local.name}`;
  }

  return undefined;
};

const getUniqueSpecifiers = (importNodes: any[]): string[] => {
  const allSpecifiers: string[] = [];

  for (const importNode of importNodes) {
    for (const specifier of importNode.specifiers) {
      const specifierText = getSpecifierText(specifier);
      if (specifierText) {
        allSpecifiers.push(specifierText);
      }
    }
  }

  return [...new Set(allSpecifiers)];
};

const createMergeDuplicateImportsFix = ({
  context,
  importNodes,
}: {
  readonly context: Rule.RuleContext;
  readonly importNodes: any[];
}) => {
  return (fixer: any) => {
    const sourceCode = context.sourceCode;
    const importKind = importNodes[0].importKind;
    const importKeyword = importKind === 'type' ? 'import type' : 'import';
    const fromClause = sourceCode.getText(importNodes[0].source);
    const uniqueSpecifiers = getUniqueSpecifiers(importNodes);
    const mergedImport = `${importKeyword} { ${uniqueSpecifiers.join(', ')} } from ${fromClause};`;
    const fixes = [fixer.replaceText(importNodes[0], mergedImport)];

    for (const duplicateImportNode of importNodes.slice(1)) {
      fixes.push(fixer.remove(duplicateImportNode));
    }

    return fixes;
  };
};

const rule: Rule.RuleModule = {
  create(context) {
    return {
      Program(node: any) {
        const sourceMap = createSourceMap(node);

        sourceMap.forEach((importNodes, source) => {
          if (importNodes.length <= 1 || !hasSameImportKind(importNodes)) {
            return;
          }

          const fix = createMergeDuplicateImportsFix({
            context,
            importNodes,
          });

          for (const importNode of importNodes.slice(1)) {
            context.report({
              data: { source },
              fix,
              messageId: 'duplicateImport',
              node: importNode,
            });
          }
        });
      },
    };
  },

  meta: {
    docs: {
      description:
        'Merge duplicate imports from the same source into a single import statement',
      recommended: false,
    },
    fixable: 'code',
    messages: {
      duplicateImport:
        'Multiple imports from "{{source}}". Merge into a single import statement.',
    },
    schema: [],
    type: 'suggestion',
  },
};

export default rule;

/**
 * Custom ESLint rule to enforce separate type imports
 * Disallows: import { type X } from 'module'
 * Enforces: import type { X } from 'module'
 */

import type { Rule } from 'eslint';

const rule: Rule.RuleModule = {
  create(context) {
    return {
      ImportDeclaration(node: any) {
        // Case 1: Check if this is already an "import type" statement with redundant inline "type" keywords
        if (node.importKind === 'type') {
          const hasRedundantInlineTypes = node.specifiers.some(
            (specifier: any) =>
              specifier.type === 'ImportSpecifier' &&
              specifier.importKind === 'type',
          );

          if (hasRedundantInlineTypes) {
            const redundantNames = node.specifiers
              .filter(
                (specifier: any) =>
                  specifier.type === 'ImportSpecifier' &&
                  specifier.importKind === 'type',
              )
              .map((specifier: any) => specifier.imported.name)
              .join(', ');

            context.report({
              data: { names: redundantNames },
              fix(fixer) {
                const sourceCode = context.sourceCode;

                // Build the fixed import by removing inline 'type' keywords
                const importedNames = node.specifiers
                  .map((specifier: any) => {
                    if (specifier.type !== 'ImportSpecifier') return null;

                    return specifier.imported.name === specifier.local.name
                      ? specifier.imported.name
                      : `${specifier.imported.name} as ${specifier.local.name}`;
                  })
                  .filter(
                    (name: null | string): name is string => name !== null,
                  )
                  .join(', ');

                const fromClause = sourceCode.getText(node.source);
                const newImport = `import type { ${importedNames} } from ${fromClause}`;

                return fixer.replaceText(node, newImport);
              },
              messageId: 'redundantInlineType',
              node,
            });
          }
          return;
        }

        // Case 2: Check if this is a regular import with inline type specifiers
        const hasInlineTypes = node.specifiers.some(
          (specifier: any) =>
            specifier.type === 'ImportSpecifier' &&
            specifier.importKind === 'type',
        );

        if (!hasInlineTypes) {
          return;
        }

        // Check if ALL imports are types (not mixed)
        const allTypes = node.specifiers.every(
          (specifier: any) =>
            specifier.type === 'ImportSpecifier' &&
            specifier.importKind === 'type',
        );

        if (!allTypes) {
          // Mixed imports - let TypeScript-ESLint handle this
          return;
        }

        // Get the imported names
        const names = node.specifiers
          .filter((specifier: any) => specifier.type === 'ImportSpecifier')
          .map((specifier: any) => specifier.imported.name)
          .join(', ');

        context.report({
          data: { names },
          fix(fixer) {
            const sourceCode = context.sourceCode;

            const importedNames = node.specifiers
              .filter((specifier: any) => specifier.type === 'ImportSpecifier')
              .map((specifier: any) => {
                return specifier.imported.name === specifier.local.name
                  ? specifier.imported.name
                  : `${specifier.imported.name} as ${specifier.local.name}`;
              })
              .join(', ');

            const fromClause = sourceCode.getText(node.source);
            const newImport = `import type { ${importedNames} } from ${fromClause}`;

            return fixer.replaceText(node, newImport);
          },
          messageId: 'noInlineTypeImport',
          node,
        });
      },
    };
  },

  meta: {
    docs: {
      description:
        'Enforce separate type imports instead of inline type imports',
      recommended: false,
    },
    fixable: 'code',
    messages: {
      noInlineTypeImport:
        'Use separate type import syntax: "import type { {{names}} }" instead of inline "type" keyword',
      redundantInlineType:
        'Redundant inline "type" keyword in import type statement. Remove "type" from: {{names}}',
    },
    schema: [],
    type: 'suggestion',
  },
};

export default rule;

// ✅ Enforces proper type suffix naming conventions
// - Function parameter types must end with 'Args' (not 'Arguments')
// - React component prop types must end with 'Props'

import type { Rule } from 'eslint';

const rule: Rule.RuleModule = {
  create(context) {
    const filename = context.filename;
    const isReactFile = filename.endsWith('.tsx') || filename.endsWith('.jsx');

    return {
      TSTypeAliasDeclaration(node: any) {
        const typeName = node.id.name;

        // Check for incorrect 'Arguments' suffix (should be 'Args')
        if (typeName.endsWith('Arguments')) {
          const suggestedName = typeName.replace(/Arguments$/, 'Args');

          context.report({
            data: {
              suggestedName,
              typeName,
            },
            fix(fixer) {
              // Find all references to this type in the file
              const fixes = [];

              // Fix the type definition itself
              fixes.push(fixer.replaceText(node.id, suggestedName));

              return fixes;
            },
            messageId: 'useArgsSuffix',
            node: node.id,
          });
        }

        // Check for incorrect 'Properties' suffix (should be 'Props')
        if (isReactFile && typeName.endsWith('Properties')) {
          const suggestedName = typeName.replace(/Properties$/, 'Props');

          context.report({
            data: {
              suggestedName,
              typeName,
            },
            fix(fixer) {
              return fixer.replaceText(node.id, suggestedName);
            },
            messageId: 'usePropsSuffix',
            node: node.id,
          });
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        'Enforce proper type suffix naming: Args for function parameters, Props for React components',
      recommended: true,
    },
    fixable: 'code',
    messages: {
      useArgsSuffix:
        "Function parameter type '{{typeName}}' should use 'Args' suffix, not 'Arguments'. Rename to '{{suggestedName}}'.",
      usePropsSuffix:
        "React component prop type '{{typeName}}' should use 'Props' suffix, not 'Properties'. Rename to '{{suggestedName}}'.",
    },
    schema: [],
    type: 'suggestion',
  },
};

export default rule;

import type { Plugin } from 'vite-plus';

import fs from 'node:fs';
import path from 'node:path';

type ManifestChunk = {
  readonly assets?: readonly string[];
  readonly file: string;
};

type ServerManifest = Record<string, ManifestChunk>;

const getServerManifestPath = (): string =>
  path.join(process.cwd(), 'build/server/.vite/manifest.json');

const readServerManifest = (): ServerManifest | undefined => {
  const serverManifestPath = getServerManifestPath();
  if (!fs.existsSync(serverManifestPath)) {
    return undefined;
  }

  return JSON.parse(
    fs.readFileSync(serverManifestPath, 'utf8'),
  ) as ServerManifest;
};

const getCssPathsFromManifest = (
  manifest: ServerManifest,
): readonly string[] => {
  const cssPaths = new Set<string>();

  for (const chunk of Object.values(manifest)) {
    if (chunk.file.endsWith('.css')) {
      cssPaths.add(chunk.file);
    }

    for (const asset of chunk.assets ?? []) {
      if (asset.endsWith('.css')) {
        cssPaths.add(asset);
      }
    }
  }

  return [...cssPaths];
};

const getClientCssFiles = ({
  clientAssetsDir,
}: {
  readonly clientAssetsDir: string;
}): readonly string[] => {
  if (!fs.existsSync(clientAssetsDir)) {
    return [];
  }

  return fs
    .readdirSync(clientAssetsDir)
    .filter((file) => file.endsWith('.css'));
};

const ensureServerCssFile = ({
  clientAssetsDir,
  clientCssFiles,
  cssPath,
  serverBuildDir,
}: {
  readonly clientAssetsDir: string;
  readonly clientCssFiles: readonly string[];
  readonly cssPath: string;
  readonly serverBuildDir: string;
}): void => {
  const serverFile = path.join(serverBuildDir, cssPath);
  if (fs.existsSync(serverFile)) {
    return;
  }

  fs.mkdirSync(path.dirname(serverFile), { recursive: true });

  if (clientCssFiles.length === 0) {
    fs.writeFileSync(serverFile, '');
    return;
  }

  const clientSource = path.join(clientAssetsDir, clientCssFiles[0]);
  fs.copyFileSync(clientSource, serverFile);
};

/**
 * Vite 8 (Rolldown) does not emit CSS assets during SSR builds, but the
 * generated manifest still references them. The react-router plugin then
 * tries to rename those (non-existent) files from the server build to the
 * client build, causing an ENOENT error.
 *
 * This plugin runs **before** react-router's writeBundle hook and
 * pre-creates any missing CSS files in the server assets directory so the
 * rename succeeds.  Content is copied from the client build when a matching
 * CSS file exists; otherwise an empty file is created as a placeholder.
 */
export const fixReactRouterAssets = (): Plugin => {
  return {
    name: 'fix-react-router-assets',
    writeBundle() {
      const manifest = readServerManifest();
      if (!manifest) {
        return;
      }

      const cssPaths = getCssPathsFromManifest(manifest);

      const serverBuildDir = path.join(process.cwd(), 'build/server');
      const clientAssetsDir = path.join(process.cwd(), 'build/client/assets');
      const clientCssFiles = getClientCssFiles({ clientAssetsDir });

      for (const cssPath of cssPaths) {
        ensureServerCssFile({
          clientAssetsDir,
          clientCssFiles,
          cssPath,
          serverBuildDir,
        });
      }
    },
  };
};

import { closePool } from '@repo/data-access/db/getPool.util';
import { join } from 'node:path';

import type {
  IngestReportArgs,
  IngestReportOrigin,
} from '../ingestion/ingestReport.types.ts';

// Relative imports for same-package modules, deliberately: this file runs
// directly via `node --experimental-strip-types` (see package.json),
// outside Vite/tsc's module graph entirely — the @repo/scan-ingestion/*
// self-referencing alias only resolves through tsconfig paths (tsc) and
// vite.config.ts's resolve.alias (Vite/Vitest), neither of which plain
// `node` execution goes through. @repo/data-access works here because it's
// a genuine cross-package import resolved via a real package.json
// `exports` map, not a self-referencing alias.
import { ingestReport } from '../ingestion/ingestReport.ts';
import {
  scannerIdSchema,
  scopeTypeSchema,
} from '../ingestion/report.schema.ts';

const REPORT_JSON_FILENAME = 'report.json';
const REPORT_MARKDOWN_FILENAME = 'report.md';

const parseArgs = (argv: readonly string[]): Record<string, string> => {
  const result: Record<string, string> = {};

  for (const arg of argv) {
    const match = /^--([^=]+)=(.*)$/.exec(arg);
    if (match?.[1] && match[2] !== undefined) {
      result[match[1]] = match[2];
    }
  }

  return result;
};

const printUsage = (): void => {
  console.error(
    'Usage: ingest.cli.ts --skill=<scannerId> --run-dir=<dir> --local-path=<path>' +
      ' [--scope-type=repo] [--scope-value=.] [--run-id=<uuid>]' +
      ' [--origin=interactive_session] [--triggered-by=<id>] [--raw-json=<filename>]',
  );
};

const run = async (): Promise<void> => {
  const flags = parseArgs(process.argv.slice(2));
  const skill = flags.skill;
  const runDir = flags['run-dir'];
  const localPath = flags['local-path'];

  if (!skill || !runDir || !localPath) {
    printUsage();
    process.exitCode = 1;
    return;
  }

  const args: IngestReportArgs = {
    localPath,
    origin: (flags.origin ?? 'interactive_session') as IngestReportOrigin,
    rawJsonPath: flags['raw-json']
      ? join(runDir, flags['raw-json'])
      : undefined,
    reportJsonPath: join(runDir, REPORT_JSON_FILENAME),
    reportMarkdownPath: join(runDir, REPORT_MARKDOWN_FILENAME),
    runId: flags['run-id'],
    scannerId: scannerIdSchema.parse(skill),
    scopeType: scopeTypeSchema.parse(flags['scope-type'] ?? 'repo'),
    scopeValue: flags['scope-value'] ?? '.',
    triggeredBy: flags['triggered-by'],
  };

  const result = await ingestReport(args);

  console.warn(
    `✅ Ingested ${result.findingsIngested} findings — project=${result.projectId} run=${result.runId} scan=${result.scanId}`,
  );
};

try {
  await run();
} catch (error: unknown) {
  console.error('❌ Ingestion failed:', error);
  process.exitCode = 1;
} finally {
  await closePool();
}

import { readEnvConfig } from '@repo/data-access/db/env.schema';
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Client } from 'pg';

const migrationsDirectory = join(
  dirname(fileURLToPath(import.meta.url)),
  'migrations',
);

const getMigrationFiles = (): readonly string[] =>
  readdirSync(migrationsDirectory)
    .filter((file) => file.endsWith('.sql'))
    .toSorted();

const ensureMigrationsTable = async (client: Client): Promise<void> => {
  await client.query(`
    CREATE SCHEMA IF NOT EXISTS cqms;
    CREATE TABLE IF NOT EXISTS cqms.schema_migrations (
      filename text PRIMARY KEY,
      applied_at timestamptz NOT NULL DEFAULT now()
    );
  `);
};

const getAppliedMigrations = async (client: Client): Promise<Set<string>> => {
  const result = await client.query<{ filename: string }>(
    'SELECT filename FROM cqms.schema_migrations',
  );
  return new Set(result.rows.map((row) => row.filename));
};

const applyMigration = async (client: Client, file: string): Promise<void> => {
  const sql = readFileSync(join(migrationsDirectory, file), 'utf8');

  await client.query('BEGIN');
  try {
    await client.query(sql);
    await client.query(
      'INSERT INTO cqms.schema_migrations (filename) VALUES ($1)',
      [file],
    );
    await client.query('COMMIT');
    console.warn(`✅ Applied: ${file}`);
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  }
};

const runMigrations = async (): Promise<void> => {
  const envConfig = readEnvConfig({ env: process.env });
  const client = new Client({
    database: envConfig.DB_NAME,
    host: envConfig.DB_HOST,
    password: envConfig.DB_PASSWORD,
    port: envConfig.DB_PORT,
    user: envConfig.DB_USER,
  });

  await client.connect();

  try {
    await ensureMigrationsTable(client);
    const applied = await getAppliedMigrations(client);

    for (const file of getMigrationFiles()) {
      if (applied.has(file)) {
        console.warn(`⏭️  Skipping already-applied migration: ${file}`);
        continue;
      }

      console.warn(`▶️  Applying migration: ${file}`);
      await applyMigration(client, file);
    }

    console.warn('✅ All migrations applied.');
  } finally {
    await client.end();
  }
};

try {
  await runMigrations();
} catch (error: unknown) {
  console.error('❌ Migration failed:', error);
  process.exitCode = 1;
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { buildFileInventory } from './buildFileInventory.util.ts';

describe('buildFileInventory', () => {
  let rootPath: string;

  beforeEach(() => {
    rootPath = mkdtempSync(join(tmpdir(), 'scan-ingestion-test-'));
    mkdirSync(join(rootPath, 'src', 'utils'), { recursive: true });
    mkdirSync(join(rootPath, 'node_modules', 'ignored-pkg'), {
      recursive: true,
    });
    writeFileSync(join(rootPath, 'src', 'App.component.tsx'), 'a\nb\nc\n');
    writeFileSync(
      join(rootPath, 'src', 'utils', 'formatDate.util.ts'),
      'export const x = 1;\n',
    );
    writeFileSync(
      join(rootPath, 'node_modules', 'ignored-pkg', 'index.js'),
      'ignored',
    );
  });

  afterEach(() => {
    rmSync(rootPath, { force: true, recursive: true });
  });

  it('collects files recursively with category/extension/nested_level', () => {
    const inventory = buildFileInventory({ rootPath });
    const paths = inventory.map((file) => file.file_path).toSorted();

    expect(paths).toEqual([
      'src/App.component.tsx',
      'src/utils/formatDate.util.ts',
    ]);
  });

  it('skips ignored directories like node_modules', () => {
    const inventory = buildFileInventory({ rootPath });

    expect(
      inventory.some((file) => file.file_path.includes('node_modules')),
    ).toBe(false);
  });

  it('computes nested_level as directory depth from root', () => {
    const inventory = buildFileInventory({ rootPath });
    const utilFile = inventory.find(
      (file) => file.file_path === 'src/utils/formatDate.util.ts',
    );

    expect(utilFile?.nested_level).toBe(2);
  });

  it('classifies category and extension correctly', () => {
    const inventory = buildFileInventory({ rootPath });
    const componentFile = inventory.find(
      (file) => file.file_path === 'src/App.component.tsx',
    );

    expect(componentFile?.file_type_category).toBe('component');
    expect(componentFile?.extension).toBe('.tsx');
    expect(componentFile?.line_count).toBe(4);
  });
});

import { readdirSync, readFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

import type { RunFileInput } from './report.schema.ts';

import { classifyFileTypeCategory } from './classifyFileTypeCategory.util.ts';

const IGNORED_DIRECTORIES = new Set([
  '.git',
  '.react-router',
  '.tmp',
  'build',
  'coverage',
  'dist',
  'node_modules',
]);

const getExtension = (fileName: string): string => {
  const dotIndex = fileName.lastIndexOf('.');
  return dotIndex === -1 ? '' : fileName.slice(dotIndex);
};

const readLineCount = (filePath: string): number | undefined => {
  try {
    return readFileSync(filePath, 'utf8').split('\n').length;
  } catch {
    return undefined;
  }
};

const walk = (
  currentPath: string,
  rootPath: string,
  results: RunFileInput[],
): void => {
  for (const entry of readdirSync(currentPath, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (IGNORED_DIRECTORIES.has(entry.name)) continue;
      walk(join(currentPath, entry.name), rootPath, results);
      continue;
    }

    if (!entry.isFile()) continue;

    const fullPath = join(currentPath, entry.name);
    const filePath = relative(rootPath, fullPath);

    results.push({
      extension: getExtension(entry.name),
      file_path: filePath,
      file_type_category: classifyFileTypeCategory(entry.name),
      line_count: readLineCount(fullPath),
      nested_level: filePath.split(sep).length - 1,
    });
  }
};

type BuildFileInventoryArgs = {
  readonly rootPath: string;
};

/**
 * Only meaningful for whole-project scopes (repo/folder) — diff-scoped
 * scans (code-smell-zen) pass no file inventory to ingestReport at all.
 */
export const buildFileInventory = ({
  rootPath,
}: BuildFileInventoryArgs): readonly RunFileInput[] => {
  const results: RunFileInput[] = [];
  walk(rootPath, rootPath, results);
  return results;
};

