import { execFileSync } from 'node:child_process';
import { realpathSync } from 'node:fs';
import { basename } from 'node:path';

// Restrict command lookup to fixed, non-writable system directories so a
// writable (potentially attacker-controlled) directory earlier in the
// inherited PATH cannot shadow the real `git` binary (Sonar S4036).
const TRUSTED_PATH = '/usr/local/bin:/usr/bin:/bin';

const runGit = (args: readonly string[], cwd: string): string | undefined => {
  try {
    return execFileSync('git', args, {
      cwd,
      encoding: 'utf8',
      env: { ...process.env, PATH: TRUSTED_PATH },
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    return undefined;
  }
};

export type ResolvedProjectPath = {
  readonly canonicalPath: string;
  readonly gitBranch: string | undefined;
  readonly gitCommitSha: string | undefined;
  readonly projectName: string;
};

type ResolveProjectPathArgs = {
  readonly localPath: string;
};

/**
 * Resolves the ad hoc interactive-session path to a stable, canonical
 * project identity: `git rev-parse --show-toplevel` (falling back to
 * localPath itself outside a git repo) then realpath-canonicalized, since
 * that's the projects.local_path unique-constraint key. Uses execFileSync
 * (no shell) rather than a string-interpolated shell command — localPath
 * ultimately traces back to user input (project registration).
 */
export const resolveProjectPath = ({
  localPath,
}: ResolveProjectPathArgs): ResolvedProjectPath => {
  const gitRoot = runGit(['rev-parse', '--show-toplevel'], localPath);
  const canonicalPath = realpathSync(gitRoot ?? localPath);

  return {
    canonicalPath,
    gitBranch: runGit(['rev-parse', '--abbrev-ref', 'HEAD'], canonicalPath),
    gitCommitSha: runGit(['rev-parse', 'HEAD'], canonicalPath),
    projectName: basename(canonicalPath),
  };
};

import { realpathSync } from 'node:fs';

type ResolveLocalPathArgs = {
  readonly localPath: string;
};

/**
 * Canonicalizes a UI-supplied path for registerProject/updateProject —
 * realpath only (resolves symlinks, normalizes `.`/`..`), no git-root
 * walking. Distinct from resolveProjectPath (matchProject.util.ts), which
 * exists specifically for the ad hoc interactive-session path's own
 * auto-matching need. Reusing that git-root-walking logic here was a real
 * bug: any subfolder of an already-registered repo silently canonicalized
 * back to that repo's root, making it impossible to register or edit a
 * project to point at a specific subfolder (e.g. `packages/ui`) distinct
 * from the whole repo — an edit to a different subfolder of the same repo
 * appeared to silently do nothing.
 */
export const resolveLocalPath = ({ localPath }: ResolveLocalPathArgs): string =>
  realpathSync(localPath);

import type { Pool } from 'pg';

import type { IngestReportArgs } from './ingestReport.types.ts';

import { resolveProjectPath } from './matchProject.util.ts';

export type ResolvedScan = {
  readonly projectId: string;
  readonly runId: string;
  readonly scanId: string;
};

const resolveExistingScan = async (
  pool: Pool,
  args: IngestReportArgs,
  runId: string,
): Promise<ResolvedScan> => {
  const runResult = await pool.query<{ project_id: string }>(
    'SELECT project_id FROM cqms.runs WHERE id = $1',
    [runId],
  );
  const projectId = runResult.rows[0]?.project_id;
  if (!projectId) {
    throw new Error(`No run found for runId=${runId}`);
  }

  const scanResult = await pool.query<{ id: string }>(
    `SELECT id FROM cqms.scans
     WHERE run_id = $1 AND scanner_id = $2
     ORDER BY created_at DESC LIMIT 1`,
    [runId, args.scannerId],
  );
  const scanId = scanResult.rows[0]?.id;
  if (!scanId) {
    throw new Error(
      `No scan found for runId=${runId}, scannerId=${args.scannerId}`,
    );
  }

  return { projectId, runId, scanId };
};

const createAdHocScan = async (
  pool: Pool,
  args: IngestReportArgs,
): Promise<ResolvedScan> => {
  const { canonicalPath, gitBranch, gitCommitSha, projectName } =
    resolveProjectPath({ localPath: args.localPath });

  const upsertResult = await pool.query<{ fn_upsert_project: string }>(
    'SELECT cqms.fn_upsert_project($1, $2) AS fn_upsert_project',
    [projectName, canonicalPath],
  );
  const projectId = upsertResult.rows[0]?.fn_upsert_project;
  if (!projectId) throw new Error('fn_upsert_project returned no id');

  const createRunResult = await pool.query<{ fn_create_run: string }>(
    'SELECT cqms.fn_create_run($1, $2, $3, $4, $5, $6) AS fn_create_run',
    [
      projectId,
      args.origin,
      JSON.stringify([args.scannerId]),
      args.triggeredBy ?? null,
      gitCommitSha ?? null,
      gitBranch ?? null,
    ],
  );
  const runId = createRunResult.rows[0]?.fn_create_run;
  if (!runId) throw new Error('fn_create_run returned no id');

  const scanInsertResult = await pool.query<{ id: string }>(
    `INSERT INTO cqms.scans (run_id, project_id, scanner_id, status, scope_type, scope_value, started_at)
     VALUES ($1, $2, $3, 'running', $4, $5, now())
     RETURNING id`,
    [runId, projectId, args.scannerId, args.scopeType, args.scopeValue],
  );
  const scanId = scanInsertResult.rows[0]?.id;
  if (!scanId) throw new Error('scan insert returned no id');

  return { projectId, runId, scanId };
};

/**
 * UI path (args.runId present): run + scan already exist (created by the
 * trigger-scan action before the job started) — just locate them. Ad hoc
 * path (no runId): resolve the project's canonical git-root path, upsert
 * the project, and create both run and scan rows here.
 */
export const resolveScan = async (
  pool: Pool,
  args: IngestReportArgs,
): Promise<ResolvedScan> =>
  args.runId
    ? resolveExistingScan(pool, args, args.runId)
    : createAdHocScan(pool, args);

