type CreateAppTsConfigArgs = {
  readonly exclude?: readonly string[];
  readonly include?: readonly string[];
  /** Extra path aliases merged on top of the default `@/*` → `./src/*` mapping — for a package's own self-referencing alias (e.g. `@repo/ui/*`) or a cross-package one. */
  readonly paths?: Record<string, readonly string[]>;
  readonly rootDirs?: readonly string[];
  readonly tsBuildInfoFile: string;
  /** Extra ambient type roots appended to the default `['vite/client']` — e.g. `'node'` for a package whose src/ mixes browser-context and Node-context (SSR entry) files. */
  readonly types?: readonly string[];
};

type CreateNodeTsConfigArgs = {
  readonly exclude?: readonly string[];
  readonly include?: readonly string[];
  /** Path aliases for this config — node configs have none by default. */
  readonly paths?: Record<string, readonly string[]>;
  readonly tsBuildInfoFile: string;
};

type TsConfig = {
  readonly compilerOptions: Record<string, unknown>;
  readonly exclude: readonly string[];
  readonly include: readonly string[];
};

const APP_TS_CONFIG: Omit<TsConfig, 'compilerOptions'> = {
  exclude: ['vite-monorepo/apps/api-server', 'miscelanious', 'utils'],
  include: [
    'src',
    '**/*',
    '**/.server/**/*',
    '**/.client/**/*',
    '.react-router/types/**/*',
  ],
};

const NODE_TS_CONFIG: Omit<TsConfig, 'compilerOptions'> = {
  exclude: ['utils'],
  include: ['vite.config.ts'],
};

const createAppCompilerOptions = ({
  paths,
  rootDirs = ['.', './.react-router/types'],
  tsBuildInfoFile,
  types = [],
}: CreateAppTsConfigArgs): Record<string, unknown> => ({
  allowImportingTsExtensions: true,
  erasableSyntaxOnly: true,
  esModuleInterop: true,
  forceConsistentCasingInFileNames: true,
  jsx: 'react-jsx',
  lib: ['ES2025', 'DOM', 'DOM.Iterable'],
  module: 'ESNext',
  moduleDetection: 'force',
  moduleResolution: 'bundler',
  noEmit: true,
  noFallthroughCasesInSwitch: true,
  noUncheckedIndexedAccess: true,
  noUncheckedSideEffectImports: true,
  noUnusedLocals: true,
  noUnusedParameters: true,
  paths: {
    '@/*': ['./src/*'],
    ...paths,
  },
  resolveJsonModule: true,
  rootDirs,
  skipLibCheck: true,
  strict: true,
  target: 'ES2025',
  tsBuildInfoFile,
  types: ['vite/client', ...types],
  useDefineForClassFields: true,
  verbatimModuleSyntax: true,
});

const createNodeCompilerOptions = ({
  paths,
  tsBuildInfoFile,
}: CreateNodeTsConfigArgs): Record<string, unknown> => ({
  allowImportingTsExtensions: true,
  erasableSyntaxOnly: true,
  forceConsistentCasingInFileNames: true,
  lib: ['ES2025'],
  module: 'ESNext',
  moduleDetection: 'force',
  moduleResolution: 'bundler',
  noEmit: true,
  noFallthroughCasesInSwitch: true,
  noUncheckedSideEffectImports: true,
  noUnusedLocals: true,
  noUnusedParameters: true,
  ...(paths && { paths }),
  skipLibCheck: true,
  strict: true,
  target: 'ES2025',
  tsBuildInfoFile,
  types: ['node'],
  verbatimModuleSyntax: true,
});

const mergeTsConfig = (
  baseConfig: TsConfig,
  overrides: Partial<TsConfig> = {},
): TsConfig => ({
  ...baseConfig,
  ...overrides,
  compilerOptions: {
    ...baseConfig.compilerOptions,
    ...overrides.compilerOptions,
  },
  exclude: overrides.exclude ?? baseConfig.exclude,
  include: overrides.include ?? baseConfig.include,
});

export const createAppTsConfig = ({
  exclude,
  include,
  paths,
  rootDirs,
  tsBuildInfoFile,
  types,
}: CreateAppTsConfigArgs): TsConfig =>
  mergeTsConfig(
    {
      compilerOptions: createAppCompilerOptions({
        paths,
        rootDirs,
        tsBuildInfoFile,
        types,
      }),
      exclude: APP_TS_CONFIG.exclude,
      include: APP_TS_CONFIG.include,
    },
    {
      exclude,
      include,
    },
  );

export const createNodeTsConfig = ({
  exclude,
  include,
  paths,
  tsBuildInfoFile,
}: CreateNodeTsConfigArgs): TsConfig =>
  mergeTsConfig(
    {
      compilerOptions: createNodeCompilerOptions({ paths, tsBuildInfoFile }),
      exclude: NODE_TS_CONFIG.exclude,
      include: NODE_TS_CONFIG.include,
    },
    {
      exclude,
      include,
    },
  );

import { createReactRouterPluginsConfig } from '@repo/vite-configs/plugins';

export const pluginsConfig = createReactRouterPluginsConfig({
  appRootUrl: import.meta.url,
  babelConfigOverrides: {
    parserOpts: {
      plugins: ['jsx'],
    },
    presets: [
      [
        '@babel/preset-typescript',
        {
          ignoreExtensions: true,
        },
      ],
    ],
  },
  babelIncludePattern: /\/src\/(?!.*\.test\.).*\.[jt]sx?(\?.*)?$/,
  // packages/ui is a component library, not a React Router app — no
  // routes.ts, no dev server, nothing for the react-router plugin or the
  // asset-manifest fixer to do. StyleX + the React Compiler babel plugin
  // still apply, same as any consuming app.
  withFixReactRouterAssetsPlugin: false,
  withReactRouterPlugin: false,
});

import { useFormContextValue } from '@repo/ui/components/Form/contexts/FormContext/useFormContextValue.hook';

export const useSetFieldValue = <TValues extends Record<string, unknown>>() => {
  const { fieldsStore } = useFormContextValue<TValues>();

  return (accessor: keyof TValues & string, value: unknown) => {
    const state = fieldsStore.get();
    const values = { ...state?.values, [accessor]: value } as TValues;

    fieldsStore.set({ values });
  };
};

import { useFieldsStore } from '@repo/ui/components/Form/contexts/FormContext/useFieldsStore.hook';
import { isFormDirty } from '@repo/ui/components/Form/utils/isFormDirty.util';

export const useGetIsFormDirty = <TValues extends Record<string, unknown>>(
  accessors: readonly (keyof TValues & string)[],
): boolean =>
  useFieldsStore<boolean, TValues>((state) =>
    isFormDirty({
      accessors,
      currentValues: state.values,
      initialValues: state.initialValues,
    }),
  );

