import { loader as browseDirectoryLoader } from '@repo/ui/routing/browseDirectory.loader';
import { mockDialogElement } from '@repo/ui/utils/tests/mockDialogElement.util';
import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from '@testing-library/react';
import { mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createRoutesStub } from 'react-router';
import {
  afterAll,
  afterEach,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from 'vitest';

import { PathBrowserModal } from './PathBrowserModal.component';

const dialogMocksRef: { current: { readonly restoreMockDialog: () => void } } =
  {
    current: { restoreMockDialog: () => {} },
  };

afterEach(() => {
  dialogMocksRef.current.restoreMockDialog();
  cleanup();
});

beforeEach(() => {
  const setup = mockDialogElement(false);
  dialogMocksRef.current = { restoreMockDialog: setup.restore };
});

describe('PathBrowserModal', () => {
  let root: string;

  beforeAll(() => {
    root = mkdtempSync(join(tmpdir(), 'path-browser-modal-test-'));
    mkdirSync(join(root, 'projects'));
    mkdirSync(join(root, 'downloads'));
  });

  afterAll(() => {
    rmSync(root, { force: true, recursive: true });
  });

  const renderModal = (props: {
    readonly onSelect?: (path: string) => void;
  }) => {
    const onSelect = props.onSelect ?? vi.fn();
    const Stub = createRoutesStub([
      {
        Component: () => (
          <PathBrowserModal
            browseAction='/_action/browse-directory'
            initialPath={root}
            isOpen
            onClose={vi.fn()}
            onSelect={onSelect}
          />
        ),
        path: '/',
      },
      {
        loader: browseDirectoryLoader,
        path: '/_action/browse-directory',
      },
    ]);

    return { onSelect, ...render(<Stub initialEntries={['/']} />) };
  };

  it('lists real subdirectories of the initial path', async () => {
    renderModal({});

    expect(await screen.findByText('projects')).not.toBeNull();
    expect(screen.getByText('downloads')).not.toBeNull();
  });

  it('drills into a subdirectory when clicked and lists its contents', async () => {
    mkdirSync(join(root, 'projects', 'cqms'));
    renderModal({});

    fireEvent.click(await screen.findByText('projects'));

    expect(await screen.findByText('cqms')).not.toBeNull();
  });

  it('calls onSelect with the currently browsed path and closes', async () => {
    const onSelect = vi.fn();
    renderModal({ onSelect });

    await screen.findByText('projects');

    fireEvent.click(
      screen.getByRole('button', { hidden: true, name: 'Select This Folder' }),
    );

    await waitFor(() => expect(onSelect).toHaveBeenCalledWith(root));
  });
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  fieldset: {
    border: 'none',
    margin: 0,
    padding: 0,
  },
});

import { useFormField } from '@repo/ui/components/Form/fields/useFormField.hook';
import { FormFieldChrome } from '@repo/ui/components/Form/FormFieldChrome/FormFieldChrome.component';
import { VirtualSelect } from '@repo/ui/components/VirtualSelect';

import type { SelectFieldProps } from './SelectField.types';

const resolveSelectedValues = (
  mode: 'multi' | 'single',
  value: unknown,
): string[] => {
  if (mode === 'multi') {
    return (value as string[] | undefined) ?? [];
  }

  if (value) {
    return [value as string];
  }

  return [];
};

export const SelectField = <TValues extends Record<string, unknown>>({
  field,
}: SelectFieldProps<TValues>) => {
  const { error, fieldId, isDisabled, setValue, value } =
    useFormField<TValues>(field);

  const selectMode = field.mode ?? 'single';
  const selected = resolveSelectedValues(selectMode, value);

  const handleChange = (nextSelected: string[]) => {
    setValue(selectMode === 'multi' ? nextSelected : (nextSelected[0] ?? ''));
  };

  return (
    <FormFieldChrome
      description={field.description}
      error={error}
      fieldId={fieldId}
      isRequired={field.clientValidation?.required}
      label={field.label}
    >
      <VirtualSelect
        isBusy={isDisabled}
        listboxId={fieldId}
        mode={selectMode}
        onChange={handleChange}
        options={field.options}
        placeholder={field.placeholder}
        selected={selected}
      />
      {/* VirtualSelect has no native form input — mirror the selection into
          hidden inputs so RR7's <Form>/fetcher.Form submits real FormData. */}
      {selected.map((selectedValue) => (
        <input
          key={selectedValue}
          name={field.accessor}
          type='hidden'
          value={selectedValue}
        />
      ))}
    </FormFieldChrome>
  );
};

// @vitest-environment jsdom

import { mockDialogElement } from '@repo/ui/utils/tests/mockDialogElement.util';
import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from '@testing-library/react';
import { createRoutesStub } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { FieldNode, FormMode } from './Form.types';

import { Form } from './Form.component';

const dialogMocksRef: { current: { readonly restoreMockDialog: () => void } } =
  {
    current: { restoreMockDialog: () => {} },
  };

beforeEach(() => {
  const setup = mockDialogElement(false);
  dialogMocksRef.current = { restoreMockDialog: setup.restore };
});

afterEach(() => {
  dialogMocksRef.current.restoreMockDialog();
  cleanup();
});

type Values = {
  readonly accepted: boolean;
  readonly bio: string;
  readonly name: string;
  readonly role: string;
};

const buildFields = (): readonly FieldNode<Values>[] => [
  {
    fields: [
      {
        accessor: 'name',
        clientValidation: { required: true },
        label: 'Name',
        type: 'text',
      },
      { accessor: 'bio', label: 'Bio', type: 'textarea' },
    ],
    type: 'row',
  },
  {
    accessor: 'accepted',
    label: 'Accept terms',
    type: 'boolean',
  },
  {
    tabs: [
      {
        fields: [
          {
            accessor: 'role',
            label: 'Role',
            options: [
              { label: 'Admin', value: 'admin' },
              { label: 'Member', value: 'member' },
            ],
            type: 'radio',
          },
        ],
        label: 'Details',
      },
    ],
    type: 'tab',
  },
];

const renderForm = ({
  action,
  fields = buildFields(),
  initialValues,
  mode,
}: {
  readonly action: (args: { readonly request: Request }) => unknown;
  readonly fields?: readonly FieldNode<Values>[];
  readonly initialValues?: Partial<Values>;
  readonly mode: FormMode;
}) => {
  const Stub = createRoutesStub([
    {
      action,
      Component: () => (
        <Form<Values>
          cancelTo='/list'
          fields={fields}
          initialValues={initialValues}
          mode={mode}
          submitLabel='Save'
        />
      ),
      path: '/',
    },
    { Component: () => <p>List Page</p>, path: '/list' },
  ]);

  return render(<Stub initialEntries={['/']} />);
};

describe('Form', () => {
  it('dispatches every leaf type through the registry and submits real FormData', async () => {
    let submittedFormData: FormData | undefined;
    const action = vi.fn(async ({ request }: { request: Request }) => {
      submittedFormData = await request.formData();
      return null;
    });

    renderForm({ action, mode: 'create' });

    fireEvent.change(screen.getByLabelText('Name', { exact: false }), {
      target: { value: 'Ada' },
    });
    fireEvent.change(screen.getByLabelText('Bio'), {
      target: { value: 'Mathematician' },
    });
    fireEvent.click(screen.getByLabelText('Accept terms'));
    fireEvent.click(screen.getByLabelText('Admin'));

    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    await waitFor(() => expect(action).toHaveBeenCalledTimes(1));
    expect(submittedFormData?.get('name')).toBe('Ada');
    expect(submittedFormData?.get('bio')).toBe('Mathematician');
    expect(submittedFormData?.get('accepted')).toBe('on');
    expect(submittedFormData?.get('role')).toBe('admin');
  });

  it('blocks submission and shows an inline error when a required field is empty', async () => {
    const action = vi.fn(async () => null);

    renderForm({ action, mode: 'create' });

    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    const alert = await screen.findByRole('alert');
    expect(alert.textContent).toBe('Name is required.');
