import { loader } from './browseDirectory.loader';

const buildArgs = (path: string) => {
  const url = `http://localhost/_action/browse-directory?path=${encodeURIComponent(path)}`;
  return {
    context: new RouterContextProvider(),
    params: {},
    pattern: '/_action/browse-directory',
    request: new Request(url),
    url: new URL(url),
  };
};

describe('browseDirectory loader', () => {
  let root: string;

  beforeAll(() => {
    root = mkdtempSync(join(tmpdir(), 'browse-directory-test-'));
    mkdirSync(join(root, 'zeta'));
    mkdirSync(join(root, 'alpha'));
    writeFileSync(join(root, 'a-file.txt'), 'not a directory');
  });

  afterAll(() => {
    rmSync(root, { force: true, recursive: true });
  });

  it('lists only real subdirectories of a real path, sorted by name', async () => {
    const result = await loader(buildArgs(root));

    expect(result.path).toBe(root);
    expect(result.error).toBeUndefined();
    expect(result.entries.map((entry) => entry.name)).toEqual([
      'alpha',
      'zeta',
    ]);
    expect(result.entries[0]?.path).toBe(join(root, 'alpha'));
  });

  it('computes parentPath as the real parent directory', async () => {
    const result = await loader(buildArgs(join(root, 'alpha')));

    expect(result.parentPath).toBe(root);
  });

  it('returns a graceful error for a path that does not exist', async () => {
    const result = await loader(buildArgs(join(root, 'does-not-exist')));

    expect(result.entries).toEqual([]);
    expect(result.error).toBeDefined();
  });
});

import type { LoaderFunctionArgs } from 'react-router';

import { readdir } from 'node:fs/promises';
import { homedir } from 'node:os';
import { dirname, resolve } from 'node:path';

import type { BrowseDirectoryResult } from './browseDirectory.types';

/**
 * Server-only directory listing for `PathField`'s browse modal. Deliberately
 * unscoped — this app runs locally and the projects it registers can live
 * anywhere on the machine, so there's no meaningful root to sandbox to (a
 * confirmed product decision, not an oversight).
 */
export const loader = async ({ request }: LoaderFunctionArgs) => {
  const url = new URL(request.url);
  const requestedPath = url.searchParams.get('path')?.trim();
  const targetPath = resolve(requestedPath || homedir());
  const parent = dirname(targetPath);
  const parentPath = parent === targetPath ? null : parent;

  try {
    const dirents = await readdir(targetPath, { withFileTypes: true });
    const entries = dirents
      .filter((entry) => entry.isDirectory())
      .map((entry) => ({
        name: entry.name,
        path: resolve(targetPath, entry.name),
      }))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      entries,
      parentPath,
      path: targetPath,
    } satisfies BrowseDirectoryResult;
  } catch {
    return {
      entries: [],
      error:
        'Could not read this directory. It may not exist, or the server may not have permission.',
      parentPath,
      path: targetPath,
    } satisfies BrowseDirectoryResult;
  }
};

