import type { ThemeMode } from '@repo/ui/types/theme.types';

import { getAppScopedCookieKey } from '@repo/ui/utils/storage';
import { readFromCookie } from '@repo/ui/utils/storage/readFromCookie.util';

import { THEME_COOKIE_NAME } from './themeCookie.constants';

/**
 * Get theme from cookie (SSR and browser-safe).
 *
 * @param cookieHeader - Raw `Cookie` header string (SSR) or undefined (client).
 * @param appId - Optional per-app id used to scope the cookie key.
 */
export const getThemeFromCookie = (
  cookieHeader: null | string | undefined,
  appId?: string,
): ThemeMode | undefined => {
  const theme = readFromCookie({
    cookieString: cookieHeader ?? undefined,
    key: getAppScopedCookieKey({ appId, key: THEME_COOKIE_NAME }),
  });

  if (theme === 'dark' || theme === 'light') {
    return theme;
  }

  return undefined;
};

import type { ThemeMode } from '@repo/ui/types/theme.types';

import { PERSIST_COOKIE_ACTION } from '@repo/ui/constants/globalSettings.constants';
import { getAppScopedCookieKey } from '@repo/ui/utils/storage';

import { THEME_COOKIE_NAME } from './themeCookie.constants';

type PersistThemeCookieEntry = {
  readonly key: string;
  readonly searchParamKey: string;
  readonly searchParamValue: string;
  readonly value: ThemeMode;
};

const persistThemeCookieServerSide = (
  theme: ThemeMode,
  appId?: string,
): void => {
  if (
    globalThis.fetch === undefined ||
    globalThis.FormData === undefined ||
    globalThis.location === undefined
  ) {
    return;
  }

  const currentUrl = `${globalThis.location.pathname}${globalThis.location.search}`;
  const entries: readonly PersistThemeCookieEntry[] = [
    {
      key: getAppScopedCookieKey({ appId, key: THEME_COOKIE_NAME }),
      searchParamKey: '',
      searchParamValue: '',
      value: theme,
    },
  ];

  const formData = new FormData();
  formData.set('currentUrl', currentUrl);
  formData.set('entries', JSON.stringify(entries));

  void globalThis.fetch(PERSIST_COOKIE_ACTION, {
    body: formData,
    method: 'POST',
  });
};

/**
 * Set theme cookie (for client-side use).
 *
 * @param theme - The theme mode to persist.
 * @param appId - Optional per-app id used to scope the cookie key so apps
 *   sharing a host (cookies ignore port) do not overwrite each other.
 */
export const setThemeCookie = (theme: ThemeMode, appId?: string): void => {
  // Persist through the React Router action so Set-Cookie comes from the server.
  persistThemeCookieServerSide(theme, appId);
};

import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

import localRules from '../eslint-local-rules/index.js';

// Resolved from tsconfigRootDir (each consuming app's own directory), never
// process.cwd() — process.cwd() is a single, fixed value for the entire
// lifetime of whatever process imports this module. That's harmless for
// this repo's own `eslint .` package.json scripts (each `cd`s into one
// app's directory before running, so cwd always matches the app being
// linted), but breaks for any single long-lived process serving multiple
// apps — e.g. an editor's ESLint extension, which stays running for the
// whole workspace and never re-execs per app. In that scenario
// process.cwd() lands on the workspace root, which has none of these
// plugins as direct dependencies (they're only installed under each app's
// own node_modules), so resolution either fails outright or falls back to
// an inconsistent module instance — which is what actually produces the
// "multiple candidate TSConfigRootDirs" symptom, not just a missing
// tsconfigRootDir parser option (that fix alone wasn't sufficient).
const resolveWorkspaceImportSpecifier = (workspaceRequire, specifier) => {
  try {
    return workspaceRequire.resolve(specifier);
  } catch (error) {
    if (
      !error ||
      typeof error !== 'object' ||
      !('code' in error) ||
      error.code !== 'ERR_PACKAGE_PATH_NOT_EXPORTED'
    ) {
      throw error;
    }

    const packageJsonPath = workspaceRequire.resolve(
      `${specifier}/package.json`,
    );
    const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf8'));
    const rootExport = packageJson.exports?.['.'];

    let entryPoint;
    if (typeof rootExport === 'string') {
      entryPoint = rootExport;
    } else if (rootExport && typeof rootExport === 'object') {
      entryPoint =
        rootExport.import ?? rootExport.default ?? rootExport.require;
    }

    entryPoint ??= packageJson.module ?? packageJson.main;

    if (typeof entryPoint !== 'string') {
      throw error;
    }

    return pathToFileURL(resolve(dirname(packageJsonPath), entryPoint)).href;
  }
};

const importFromWorkspace = async (workspaceRequire, specifier) => {
  return await import(
    resolveWorkspaceImportSpecifier(workspaceRequire, specifier)
  );
};

